template<class T>bool at(uintptr_t p,size_t offset,T& value,std::string& e){if(!p||p>UINTPTR_MAX-offset)return fail(e,"Day native address extent invalid");return memory.copy(p+offset,&value,sizeof value,e);}
bool ap(uintptr_t p,uintptr_t image,uintptr_t expected,std::string& e){uintptr_t value=0;return at(p,0,value,e)&&(value==image+expected||fail(e,"Day actual class addresspoint differs"));}
using Allocate=void*(*)(size_t);using Object=void(*)(void*);using DeleteArray=void(*)(void*);
DWORD allocate(Allocate f,size_t bytes,void** out)noexcept{__try{*out=f(bytes);return 0;}__except(EXCEPTION_EXECUTE_HANDLER){return GetExceptionCode();}}
DWORD object(Object f,void* p)noexcept{__try{f(p);return 0;}__except(EXCEPTION_EXECUTE_HANDLER){return GetExceptionCode();}}
DWORD copy_array(uintptr_t target,const uintptr_t* source,size_t count)noexcept{__try{std::memcpy(reinterpret_cast<void*>(target),source,count*sizeof(uintptr_t));return 0;}__except(EXCEPTION_EXECUTE_HANDLER){return GetExceptionCode();}}
bool same_base(const Pin& a,const Pin& b){return a.context==b.context&&a.binding==b.binding&&a.common_epoch==b.common_epoch&&a.image==b.image&&a.world==b.world&&a.clock==b.clock&&a.business==b.business&&a.thread==b.thread&&a.selected==b.selected&&a.pause==b.pause;}
uintptr_t scalar(uintptr_t owner,size_t index){return index<5?owner+0x1c+index*4:owner+0x30+((index-5)/2)*0x48+0x18+((index-5)%2)*4;}
std::array<int32_t,45> fields(const Record& r){std::array<int32_t,45> out{};size_t i=0;for(auto v:r.values)out[i++]=v;for(auto pair:r.lines)for(auto v:pair)out[i++]=v;return out;}
