bool NativePort::record_at(uintptr_t owner,uintptr_t image,Record& out,std::string& e){
    out={};if(owner>UINTPTR_MAX-0x5d0)return fail(e,"Day actual Record requires dv2/5D0 extent");
    constexpr size_t extent=0x30+19*0x48+0x20+sizeof(int32_t);
    static_assert(extent==0x5ac);
    std::array<unsigned char,extent> bytes{};
    if(!read_native_block(memory,owner,bytes.data(),bytes.size(),e))return false;
    auto field=[&](size_t offset,auto& value){std::memcpy(&value,bytes.data()+offset,sizeof value);};
    uintptr_t type=0;int32_t version=0;field(0,type);field(0x18,version);
    if(type!=image+0x1712c00)return fail(e,"Day actual class addresspoint differs");
    if(version!=2)return fail(e,"Day actual Record requires dv2/5D0 extent");
    for(size_t i=0;i<5;++i)field(0x1c+i*4,out.values[i]);
    for(size_t i=0;i<20;++i){const auto line=0x30+i*0x48;int32_t category=-1;
        field(line,type);field(line+0x20,category);
        if(type!=image+0x171d0d0)return fail(e,"Day actual class addresspoint differs");
        if(category!=int32_t(i))return fail(e,"Day actual LineItem category differs");
        field(line+0x18,out.lines[i][0]);field(line+0x1c,out.lines[i][1]);
    }
    return true;
}
bool NativePort::read_once(NativeHistory& out,std::string& e,bool share_metadata,subscriber_lifecycle_append::QuestEditBatch* held){if(held&&!subscriber_lifecycle_append::verify_quest_edits_held(*held,e))return false;apply_timing::PageReadScope pages(!share_metadata||!apply_timing::page_read_scope);out={};uintptr_t image=0;uint32_t thread=0;std::string sha;if(!native::read_resolver_receipt(image,thread,sha,e))return false;if(thread!=GetCurrentThreadId()||image!=uintptr_t(GetModuleHandleW(nullptr))||sha!="bbab2dc68babcc644d0a1679548bf1e334b6c52aea669c3f61f6cb9d45c1aaf6")return fail(e,"Day actual module/Mainthread differs");auto& local=action_session::selected_session();Context actual;if(!local.current(actual,e)||actual!=context_)return fail(e,e.empty()?"Day actual Session differs":e);building_mixed_identity::opened_file::CurrentWorld world;if(!native_open_runtime::read_current_world(world,e)||world.world_epoch!=binding_.native_epoch||world.generation!=binding_.native_generation||!world.world||!world.state)return fail(e,e.empty()?"Day actual World/generation differs":e);native::WorldStatus status;if(!native::read_world_status(status,e))return false;if(held){if(status.saves_in_progress!=1||status.edit_operations)return fail(e,"Day Quest held scope requires1 save and0 edits saves="+std::to_string(status.saves_in_progress)+" edits="+std::to_string(status.edit_operations));}else if(status.saves_in_progress||status.edit_operations)return fail(e,"Day actual Save/EditIdle requires0 saves="+std::to_string(status.saves_in_progress)+" edits="+std::to_string(status.edit_operations));auto& p=out.pin;p.context=actual;p.binding=binding_;p.common_epoch=net::current_world_epoch();p.world=uintptr_t(world.world);p.image=image;p.thread=thread;if(!p.common_epoch)return fail(e,"Day actual common Sidecar epoch absent");if(!at(image,0x13df9a0,p.clock,e)||!ap(p.clock,image,0x17499d0,e)||!at(image,0x13df220,p.business,e)||!ap(p.business,image,0x16d97e0,e)||p.business>UINTPTR_MAX-0x110||!ap(p.business+0x60,image,0x16ec280,e)||!at(p.business,0x68,p.history,e)||!at(p.business,0x70,p.history_count,e)||!at(p.business,0x74,p.history_capacity,e)||!at(p.business,0x100,p.record,e))return false;if(p.history_count<1||p.history_count>int32_t(history_limit*2)||p.history_capacity<p.history_count||!p.history)return fail(e,"Day actual bounded History shape differs");for(int32_t i=0;i<p.history_count;++i){uintptr_t owner=0;Record row;if(!at(p.history,size_t(i)*8,owner,e)||!record_at(owner,image,row,e))return false;if(std::find(out.owners.begin(),out.owners.end(),owner)!=out.owners.end())return fail(e,"Day actual History duplicate pointer");out.owners.push_back(owner);out.records.push_back(row);}if(std::find(out.owners.begin(),out.owners.end(),p.record)==out.owners.end())return fail(e,"Day actual Current Record outside owned History");for(size_t i=0;i<6;++i)if(!at(p.clock,0x38+i*4,p.values.calendar[i],e))return false;if(!at(p.clock,0x58,p.selected,e)||!at(p.clock,0x5c,p.pause,e)||!at(p.business,0x38,p.values.cash,e))return false;if(held&&(p.selected!=0.0f||p.pause!=0.0f))return fail(e,"Day Quest held Clock requires selected0 pause0");Record current;if(!record_at(p.record,image,current,e))return false;p.values.record=current.values;p.values.lines=current.lines;uintptr_t end_data=0,end_current=0;int32_t end_count=0,end_cap=0;if(!at(p.business,0x68,end_data,e)||!at(p.business,0x70,end_count,e)||!at(p.business,0x74,end_cap,e)||!at(p.business,0x100,end_current,e)||end_data!=p.history||end_count!=p.history_count||end_cap!=p.history_capacity||end_current!=p.record)return fail(e,e.empty()?"Day actual History changed during read":e);e.clear();return true;}
bool NativePort::read(NativeHistory& out,std::string& e){apply_timing::Scope measured(apply_timing::Part::DayRead);apply_timing::PageReadScope pages(!apply_timing::page_read_scope);NativeHistory first,second;if(!read_once(first,e,true)||!read_once(second,e,true))return false;if(first.pin!=second.pin||first.owners!=second.owners||first.records!=second.records)return fail(e,"Day actual History/45 fields changed during double read");out=std::move(first);return true;}
bool NativePort::read_quest_held(NativeHistory& out,subscriber_lifecycle_append::QuestEditBatch& held,std::string& e){
    apply_timing::Scope measured(apply_timing::Part::DayRead);
    apply_timing::PageReadScope pages(!apply_timing::page_read_scope);
    NativeHistory first,second;
    if(!read_once(first,e,true,&held)||!read_once(second,e,true,&held))return false;
    if(first.pin!=second.pin||first.owners!=second.owners||first.records!=second.records)
        return fail(e,"Day actual History/45 fields changed during double read");
    out=std::move(first);return true;
}
bool NativePort::rebind_snapshot(const Context& c,const Binding& b,std::string& e){NativePort fresh(c,b,fence_);NativeHistory h;if(!fresh.read(h,e))return false;for(auto i=resources_.begin();i!=resources_.end();){if(i->second==Resource::Published)i=resources_.erase(i);else ++i;}context_=c;binding_=b;e.clear();return true;}
bool NativePort::current(const Pin& expected,std::string& e){NativeHistory actual;if(!read(actual,e))return false;if(!same_base(actual.pin,expected)||actual.pin.selected!=0||!fence_.read_current_fence(actual.pin,e))return fail(e,e.empty()?"Day actual owner/GameUpdate/fence differs":e);return true;}
bool prepare_original_guards(std::string& e){if(originals_prepared){e.clear();return true;}const uintptr_t image=uintptr_t(GetModuleHandleW(nullptr));for(const auto& body:guards::bodies){std::vector<unsigned char> bytes(body.size);if(!memory.copy(image+body.rva,bytes.data(),bytes.size(),e))return false;if(std::memcmp(bytes.data(),body.bytes,body.size))return fail(e,"Day native original whole body differs rva="+std::to_string(body.rva));}originals_prepared=true;return true;}
bool NativePort::write_closed(const NativeHistory& before,uintptr_t owner,const Record& expected,const Record& target,std::string& e){if(!current(before.pin,e)||std::find(before.owners.begin(),before.owners.end(),owner)==before.owners.end())return fail(e,e.empty()?"Day closed Record not actual owned member":e);Record actual;if(!record_at(owner,before.pin.image,actual,e)||actual!=expected)return fail(e,e.empty()?"Day closed exact prior45 fields differ":e);const auto old=fields(expected),after=fields(target);for(size_t i=0;i<old.size();++i)if(old[i]!=after[i]){if(!current(before.pin,e)||!compare_fixed_i32(scalar(owner,i),old[i],after[i],e))return false;}return record_at(owner,before.pin.image,actual,e)&&actual==target;}
bool NativePort::create(const Record& target,uintptr_t& out,std::string& e){out=0;if(!originals_prepared)return fail(e,"Day native C1/Init guards not prepared");NativeHistory h;if(!read(h,e)||!current(h.pin,e))return false;void* allocated=nullptr;auto code=allocate(reinterpret_cast<Allocate>(h.pin.image+0xa02670),0x5d0,&allocated);if(code||!allocated)return fail(e,"Day native Record allocation failed SEH="+std::to_string(code));const auto owner=uintptr_t(allocated);resources_[owner]=Resource::Allocated;code=object(reinterpret_cast<Object>(h.pin.image+0x5f740),allocated);if(code){resources_[owner]=Resource::Unknown;return fail(e,"Day native Record C1 SEH="+std::to_string(code)+"; allocation retained");}resources_[owner]=Resource::Constructed;code=object(reinterpret_cast<Object>(h.pin.image+0x5f830),allocated);if(code){resources_[owner]=Resource::Unknown;return fail(e,"Day native Record Init SEH="+std::to_string(code)+"; allocation retained");}resources_[owner]=Resource::Initialized;// Init leaves LoanTotal untouched. Read the actual constructed value before its exact CAS.
    Record zero;if(!record_at(owner,h.pin.image,zero,e)){resources_[owner]=Resource::Unknown;return false;}const auto before=fields(zero),after=fields(target);for(size_t i=0;i<before.size();++i)if(before[i]!=after[i]&&(!current(h.pin,e)||!compare_fixed_i32(scalar(owner,i),before[i],after[i],e))){resources_[owner]=Resource::Unknown;return false;}Record actual;if(!record_at(owner,h.pin.image,actual,e)||actual!=target){resources_[owner]=Resource::Unknown;return fail(e,e.empty()?"Day native C1/Init45 field readback differs":e);}out=owner;e.clear();return true;}
bool NativePort::append(const NativeHistory& expected,uintptr_t made,const Record& target,std::string& e){if(!originals_prepared||!resources_.contains(made)||resources_.at(made)!=Resource::Initialized||!current(expected.pin,e))return fail(e,e.empty()?"Day actual private native Record resource missing":e);NativeHistory h;if(!read(h,e)||!same_base(h.pin,expected.pin)||h.owners!=expected.owners||h.pin.record!=expected.pin.record)return fail(e,e.empty()?"Day exact History before append differs":e);Record actual;if(!record_at(made,h.pin.image,actual,e)||actual!=target||std::find(h.owners.begin(),h.owners.end(),made)!=h.owners.end())return fail(e,e.empty()?"Day private Record target/unique ownership differs":e);uintptr_t data=h.pin.history;const int32_t count=h.pin.history_count;int32_t capacity=h.pin.history_capacity;
    if(count==capacity){const int32_t next=std::max(4,capacity*2);void* array=nullptr;const auto code=allocate(reinterpret_cast<Allocate>(h.pin.image+0xa026c0),size_t(next)*8,&array);if(code||!array)return fail(e,"Day native History array allocation SEH="+std::to_string(code));const auto fresh=uintptr_t(array);retained_arrays_.push_back(fresh);const auto copied=copy_array(fresh,h.owners.data(),h.owners.size());if(copied)return fail(e,"Day native History array copy SEH="+std::to_string(copied));if(!current(h.pin,e)||!compare_owned_pointer(h.pin.business+0x68,data,fresh,e)||!compare_fixed_i32(h.pin.business+0x74,capacity,next,e))return false;const auto freed=object(reinterpret_cast<Object>(h.pin.image+0xa01280),reinterpret_cast<void*>(data));if(freed)return fail(e,"Day native old History delete[] SEH="+std::to_string(freed));retained_arrays_.erase(std::remove(retained_arrays_.begin(),retained_arrays_.end(),fresh),retained_arrays_.end());data=fresh;capacity=next;}
    if(count>=capacity)return fail(e,"Day actual History capacity must exceed count before append");uintptr_t spare=0;if(!at(data,size_t(count)*8,spare,e)||!compare_owned_pointer(data+size_t(count)*8,spare,made,e)||!compare_fixed_i32(h.pin.business+0x70,count,count+1,e))return false;resources_[made]=Resource::Published;e.clear();return true;}
bool NativePort::commit_current(const NativeHistory& before,uintptr_t next,const Frame& frame,std::string& e){if(!live_host_state::valid(frame,e)||frame.session!=context_.session||frame.snapshot!=context_.snapshot_uuid||frame.epoch!=before.pin.common_epoch||!current(before.pin,e))return fail(e,e.empty()?"Day Current commit authenticated frame differs":e);NativeHistory h;if(!read(h,e)||h.pin.record!=before.pin.record||h.owners.back()!=next||!resources_.contains(next)||resources_.at(next)!=Resource::Published)return fail(e,e.empty()?"Day Current commit requires actual appended native resource":e);Record actual;if(!record_at(next,h.pin.image,actual,e)||actual!=record(frame.values))return fail(e,e.empty()?"Day new Current45 fields differ from Host":e);if(!compare_owned_pointer(h.pin.business+0x100,before.pin.record,next,e))return false;for(size_t i=0;i<6;++i){if(!current(before.pin,e)||!compare_fixed_i32(h.pin.clock+0x38+i*4,before.pin.values.calendar[i],frame.values.calendar[i],e))return false;}int32_t cash=0;if(!at(h.pin.business,0x38,cash,e)||cash!=before.pin.values.cash||!compare_fixed_i32(h.pin.business+0x38,cash,frame.values.cash,e))return fail(e,e.empty()?"Day exact Business cash before differs":e);return true;}
bool NativePort::prune(const NativeHistory& expected,size_t keep,std::string& e){if(keep!=history_limit||!current(expected.pin,e))return fail(e,e.empty()?"Day prune permits exact native retained10 only":e);NativeHistory h;if(!read(h,e)||h.owners!=expected.owners||h.pin.record!=expected.pin.record)return fail(e,e.empty()?"Day actual History before prune differs":e);while(h.owners.size()>keep){const auto retired=h.owners.front();if(retired==h.pin.record)return fail(e,"Day prune would retire actual Current Record");const auto remaining=h.owners.size()-1;if(!current(h.pin,e))return false;const auto moved=copy_array(h.pin.history,h.owners.data()+1,remaining);if(moved)return fail(e,"Day native History shift SEH="+std::to_string(moved));if(!compare_fixed_i32(h.pin.business+0x70,int32_t(h.owners.size()),int32_t(remaining),e))return false;const auto destroyed=object(reinterpret_cast<Object>(h.pin.image+0xbee970),reinterpret_cast<void*>(retired));if(destroyed)return fail(e,"Day native Record D0 SEH="+std::to_string(destroyed));resources_.erase(retired);h.owners.erase(h.owners.begin());h.records.erase(h.records.begin());}e.clear();return true;}
